import {readHistory,saveHistory} from './history-preferences.js';
export function createHistorySettings(getAccounts){
 const card=document.createElement('details');card.className='settings-card history-settings';card.open=true;
 card.innerHTML=`<summary>聊天记录 <span class="settings-badge pending">桌面版待接入</span></summary><div class="history-form">
 <div class="history-row"><label for="historyEnabled">保存聊天记录</label><div><label class="history-check"><input id="historyEnabled" type="checkbox">保存（仅保存在本机，不上传）</label><p class="settings-caption">用于保存已打开的 WhatsApp 对话文字、译文和图片。Facebook 暂不支持。</p><p class="settings-caption">当前仅保存设置偏好；聊天采集、本机加密存储及离线查看尚未接入。</p></div></div>
 <div class="history-row"><label for="historyAutoExport">每天自动导出</label><div><div class="history-inline"><label class="history-check"><input id="historyAutoExport" type="checkbox">每天</label><input id="historyTime" type="time" aria-label="每天自动导出时间"></div><p class="settings-caption">桌面版按电脑本地时间导出当天记录为可离线查看的网页；错过时间将在下次打开软件时补导出。</p></div></div>
 <div class="history-row"><label for="historyDirectory">导出到</label><div><div class="history-inline"><input id="historyDirectory" placeholder="使用桌面版默认导出目录" aria-label="聊天记录导出目录"><button type="button" class="button quiet" data-history="directory">更换…</button><button type="button" class="button quiet" data-history="open">打开文件夹</button></div><p class="settings-caption">当前可填写 Windows 路径并保存偏好，不创建或移动文件。</p></div></div>
 <div class="history-row"><label for="historyRetention">本机保存</label><div><select id="historyRetention"><option value="30">30 天</option><option value="90">90 天</option><option value="180">180 天</option><option value="365">1 年</option><option value="forever">永久保留</option></select><p class="settings-caption">桌面版将按期限清理本机聊天记录，已导出的文件不受影响。自动清理尚未接入。</p></div></div>
 <div class="history-row"><span>已保存</span><div><strong class="history-saved">— 条消息 · — 张图片 · —</strong><p class="settings-caption">尚未连接本机聊天记录库。</p></div></div>
 <div class="history-row"><label for="historyAccount">同步历史聊天记录</label><div><div class="history-inline"><select id="historyAccount" aria-label="同步历史记录的 WhatsApp 账户"></select><select aria-label="历史同步范围"><option>最近 7 天</option><option selected>最近 30 天</option><option>最近 90 天</option><option>全部可用历史</option></select><button type="button" class="button quiet" disabled title="真实 WhatsApp 会话与历史同步尚未接入">开始同步</button></div><p class="settings-caption">可选择全部 WhatsApp 账号或单个账号，补充此前未保存的历史。桌面版将只读取消息，不发送；可获取范围取决于 WhatsApp 网页已同步的历史。</p></div></div>
 <div class="history-row"><label for="historyExportRange">手动导出</label><div><div class="history-inline"><select id="historyExportRange"><option value="all">全部（每个客户一个文件）</option><option value="day">指定日期</option></select><input type="date" aria-label="导出日期" id="historyExportDate" hidden><button type="button" class="button quiet" disabled title="尚无可导出的真实聊天记录">导出</button></div><p class="settings-caption">全部导出将按客户生成网页文件；也可只导出指定一天的记录。</p></div></div>
 <div class="history-row"><span>上次自动导出</span><span class="settings-caption">尚未执行</span></div>
 </div><p class="settings-feedback history-feedback" role="status"></p>`;
 const q=s=>card.querySelector(s),storage={getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)};let prefs=readHistory(storage);
 function feedback(text,error=false){q('.history-feedback').textContent=text;q('.history-feedback').classList.toggle('error',error)}
 function paint(){q('#historyEnabled').checked=prefs.enabled;q('#historyAutoExport').checked=prefs.autoExport;q('#historyAutoExport').disabled=!prefs.enabled;q('#historyTime').value=prefs.time;q('#historyTime').disabled=!prefs.enabled||!prefs.autoExport;q('#historyDirectory').value=prefs.directory;q('#historyRetention').value=prefs.retention}
 for(const [selector,key] of [['#historyEnabled','enabled'],['#historyAutoExport','autoExport'],['#historyTime','time'],['#historyDirectory','directory'],['#historyRetention','retention']])q(selector).onchange=e=>{try{if(key==='time'&&!e.target.value)throw Error('请选择有效的导出时间。');prefs=saveHistory(storage,{...prefs,[key]:e.target.type==='checkbox'?e.target.checked:e.target.value});feedback('偏好已保存；真实聊天记录功能待桌面版接入。');paint()}catch(error){feedback(error.message||'设置保存失败，请重试。',true);paint()}};
 q('[data-history=directory]').onclick=()=>{q('#historyDirectory').focus();feedback('当前可手动填写完整 Windows 目录；磁盘目录选择将在桌面版接入。')};q('[data-history=open]').onclick=()=>feedback('当前无法打开本机文件夹，此操作将在 Windows 桌面版接入。');
 q('#historyExportRange').onchange=e=>{q('#historyExportDate').hidden=e.target.value!=='day'};
 function refresh(){prefs=readHistory(storage);paint();const select=q('#historyAccount'),previous=select.value;select.replaceChildren();const accounts=getAccounts();if(accounts.length){const all=document.createElement('option');all.value='all-whatsapp';all.textContent='全部 WhatsApp 账号';select.append(all)}for(const a of accounts){const option=document.createElement('option');option.value=a.id;option.textContent=a.name;select.append(option)}if(!accounts.length){const option=document.createElement('option');option.textContent='暂无 WhatsApp 账户';select.append(option)}select.disabled=!accounts.length;if(previous==='all-whatsapp'||accounts.some(a=>a.id===previous))select.value=previous}
 refresh();return {element:card,refresh};
}
